"use client";

import type { ReactNode } from "react";
import { useState } from "react";
import {
	ActivityIcon,
	BarChart3Icon,
	BellIcon,
	ChevronRightIcon,
	CommandIcon,
	CreditCardIcon,
	GraduationCapIcon,
	HelpCircleIcon,
	LayoutGridIcon,
	LifeBuoyIcon,
	ListChecksIcon,
	LogOutIcon,
	MessageSquareTextIcon,
	PlugIcon,
	PlusIcon,
	SearchIcon,
	SendIcon,
	Settings2Icon,
	SettingsIcon,
	UserIcon,
	UsersIcon,
	XIcon,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
	Breadcrumb,
	BreadcrumbItem,
	BreadcrumbList,
	BreadcrumbPage,
} from "@/components/ui/breadcrumb";
import { Button } from "@/components/ui/button";
import {
	Collapsible,
	CollapsibleContent,
	CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuGroup,
	DropdownMenuItem,
	DropdownMenuLabel,
	DropdownMenuSeparator,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Separator } from "@/components/ui/separator";
import {
	Tooltip,
	TooltipContent,
	TooltipTrigger,
} from "@/components/ui/tooltip";
import { Kbd, KbdGroup } from "./app-shell-kbd";
import {
	Sidebar,
	SidebarContent,
	SidebarFooter,
	SidebarGroup,
	SidebarGroupLabel,
	SidebarHeader,
	SidebarInset,
	SidebarMenu,
	SidebarMenuButton,
	SidebarMenuItem,
	SidebarMenuSub,
	SidebarMenuSubButton,
	SidebarMenuSubItem,
	SidebarProvider,
	SidebarTrigger,
} from "./app-shell-sidebar";

/* ----------------------------------------------------------------------------
 * Navigation data
 * --------------------------------------------------------------------------*/

export type SidebarNavItem = {
	title: string;
	path?: string;
	icon?: ReactNode;
	subItems?: SidebarNavItem[];
};

export type SidebarNavGroup = {
	label?: string;
	items: SidebarNavItem[];
};

export const navGroups: SidebarNavGroup[] = [
	{
		items: [{ title: "Overview", path: "#/overview", icon: <LayoutGridIcon /> }],
	},
	{
		label: "Today",
		items: [
			{ title: "Queue", path: "#/queue", icon: <ListChecksIcon /> },
			{
				title: "Team insights",
				path: "#/team-insights",
				icon: <BarChart3Icon />,
			},
		],
	},
	{
		label: "Inbox",
		items: [
			{
				title: "Conversations",
				icon: <MessageSquareTextIcon />,
				subItems: [
					{ title: "Unassigned", path: "#/inbox/unassigned" },
					{ title: "Assigned to me", path: "#/inbox/assigned" },
					{ title: "Recently closed", path: "#/inbox/closed" },
				],
			},
			{ title: "Customers", path: "#/customers", icon: <UsersIcon /> },
			{ title: "Channels", path: "#/channels", icon: <PlugIcon /> },
		],
	},
	{
		label: "Organization",
		items: [
			{
				title: "Workspace",
				icon: <SettingsIcon />,
				subItems: [
					{ title: "Branding", path: "#/workspace/branding" },
					{ title: "Team & roles", path: "#/workspace/team" },
					{ title: "API keys", path: "#/workspace/api-keys" },
					{ title: "Webhooks", path: "#/workspace/webhooks" },
					{ title: "Billing", path: "#/workspace/billing" },
				],
			},
			{ title: "Settings", path: "#/settings", icon: <Settings2Icon /> },
		],
	},
];

export const footerNavLinks: SidebarNavItem[] = [
	{ title: "Help Center", path: "#/help", icon: <HelpCircleIcon /> },
	{ title: "System status", path: "#/status", icon: <ActivityIcon /> },
];

export const navLinks: SidebarNavItem[] = [
	...navGroups.flatMap((group) =>
		group.items.flatMap((item) =>
			item.subItems?.length ? [item, ...item.subItems] : [item]
		)
	),
	...footerNavLinks,
];

const user = {
	name: "Maya Chen",
	email: "maya@relay.app",
	avatar: "https://i.pravatar.cc/150?img=47",
};

/* ----------------------------------------------------------------------------
 * Shell
 * --------------------------------------------------------------------------*/

export function AppShell({
	children,
	pathname = "#/overview",
}: {
	children: React.ReactNode;
	pathname?: string;
}) {
	return (
		<div className="overflow-hidden">
			<SidebarProvider className="relative h-svh">
				<AppSidebar pathname={pathname} />
				<SidebarInset className="md:peer-data-[variant=inset]:ml-0">
					<AppHeader pathname={pathname} />
					<div className="flex flex-1 flex-col gap-4 overflow-y-auto p-4 md:p-6">
						{children}
					</div>
				</SidebarInset>
			</SidebarProvider>
		</div>
	);
}

export function AppHeader({ pathname }: { pathname?: string }) {
	const activeItem = navLinks.find((item) => item.path === pathname);
	return (
		<header
			className={cn(
				"sticky top-0 z-50 flex h-14 shrink-0 items-center justify-between gap-2 border-b px-4 md:px-6"
			)}
		>
			<div className="flex items-center gap-3">
				<CustomSidebarTrigger />
				<Separator
					className="mr-2 h-4 data-[orientation=vertical]:self-center"
					orientation="vertical"
				/>
